package com.rgapro1.ocaso;

import android.Manifest;
import android.app.AlertDialog;
import android.content.ClipData;
import android.content.Intent;
import android.content.SharedPreferences;
import android.content.pm.PackageManager;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Color;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.Bundle;
import android.provider.MediaStore;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import androidx.core.content.ContextCompat;
import androidx.core.content.FileProvider;
import androidx.fragment.app.FragmentActivity;
import com.google.mlkit.vision.common.InputImage;
import com.google.mlkit.vision.text.TextRecognition;
import com.google.mlkit.vision.text.TextRecognizer;
import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.util.*;

/** Main application UI. OCR is classified first; only approved fields are shown per document type. */
public class MainActivity extends FragmentActivity {
    private static final int NAVY=Color.rgb(7,26,58), BLUE=Color.rgb(25,133,224), BG=Color.rgb(247,249,252), TEXT=Color.rgb(28,39,54), MUTED=Color.rgb(103,115,132);
    private static final int CAMERA_REQ=7101, IMAGE_REQ=7102;
    private SharedPreferences prefs; private String currentUser=""; private File cameraFile;
    private final ArrayList<String> sessionPaths=new ArrayList<>();
    protected int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView tv(String s,float z,int c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(b?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);v.setPadding(dp(6),dp(6),dp(6),dp(6));return v;}
    private EditText edit(String h){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);e.setTextSize(16);e.setPadding(dp(14),0,dp(14),0);e.setBackgroundColor(Color.WHITE);return e;}
    private Button button(String s,boolean p){Button b=new Button(this);b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setTextColor(p?Color.WHITE:TEXT);b.setGravity(Gravity.CENTER);b.setBackgroundColor(p?BLUE:Color.WHITE);return b;}
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(NAVY);prefs=getSharedPreferences("rgapro_local",MODE_PRIVATE);if(!prefs.contains("user"))createUser();else showLogin();}
    private void createUser(){LinearLayout l=col();l.setBackgroundColor(BG);l.setPadding(dp(24),dp(24),dp(24),dp(24));l.setGravity(Gravity.CENTER_HORIZONTAL);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_rgapro);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);l.addView(logo,new LinearLayout.LayoutParams(-1,dp(180)));l.addView(tv("RGA PRO",30,NAVY,true));l.addView(tv("Acceso seguro",18,TEXT,true));EditText u=edit("Usuario"),p=edit("PIN de 6 dígitos"),p2=edit("Repite el PIN");p.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);p2.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);l.addView(u,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(p,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(p2,new LinearLayout.LayoutParams(-1,dp(54)));Button go=button("Crear acceso",true);l.addView(go,new LinearLayout.LayoutParams(-1,dp(56)));go.setOnClickListener(v->{String pin=p.getText().toString();if(u.getText().toString().trim().isEmpty()||!pin.matches("\\d{6}")||!pin.equals(p2.getText().toString())){Toast.makeText(this,"Usa un PIN de 6 dígitos y repítelo",Toast.LENGTH_LONG).show();return;}prefs.edit().putString("user",u.getText().toString().trim()).putString("pin",pin).putBoolean("biometric",true).apply();currentUser=u.getText().toString().trim();home();});l.addView(tv("El PIN y la cartera se protegen con Android Keystore.",13,MUTED,false));setContentView(l);}
    private void showLogin(){LinearLayout l=col();l.setBackgroundColor(BG);l.setPadding(dp(24),dp(24),dp(24),dp(24));l.setGravity(Gravity.CENTER_HORIZONTAL);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_rgapro);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);l.addView(logo,new LinearLayout.LayoutParams(-1,dp(160)));l.addView(tv("RGA PRO",30,NAVY,true));l.addView(tv("Cartera segura",18,TEXT,true));Button key=button("Entrar con PIN",true);l.addView(key,new LinearLayout.LayoutParams(-1,dp(56)));key.setOnClickListener(v->login());setContentView(l);}
    private void login(){EditText e=edit("PIN de 6 dígitos");e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);AlertDialog d=new AlertDialog.Builder(this).setTitle("Acceso").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Entrar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(prefs.getString("pin","").equals(e.getText().toString())){d.dismiss();currentUser=prefs.getString("user","");home();}else e.setError("PIN incorrecto");}));d.show();}
    private void home(){LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout head=col();head.setBackgroundColor(NAVY);head.setPadding(dp(18),dp(8),dp(18),dp(8));head.addView(tv("RGA PRO",25,Color.WHITE,true));head.addView(tv("Gestión de clientes y pólizas · "+currentUser,14,Color.WHITE,false));root.addView(head,new LinearLayout.LayoutParams(-1,dp(78)));ScrollView s=new ScrollView(this);LinearLayout body=col();body.setPadding(dp(18),dp(18),dp(18),dp(24));body.addView(tv("OCR inteligente",23,TEXT,true));body.addView(tv("Primero identifica el documento y después muestra solo sus campos.",14,MUTED,false));Button scan=button("📷  ESCANEAR DNI / NIE O PÓLIZA",true);body.addView(scan,new LinearLayout.LayoutParams(-1,dp(64)));scan.setOnClickListener(v->scanDocument());Button gallery=button("🖼  SELECCIONAR FOTO",false);body.addView(gallery,new LinearLayout.LayoutParams(-1,dp(56)));gallery.setOnClickListener(v->pickImage());body.addView(tv("Vencimientos",19,TEXT,true));LinearLayout expiry=col();populateExpiries(expiry);body.addView(expiry);Button clients=button("👤  Ver clientes",false);body.addView(clients,new LinearLayout.LayoutParams(-1,dp(54)));clients.setOnClickListener(v->listRecords(false));Button policies=button("🛡  Ver pólizas",false);body.addView(policies,new LinearLayout.LayoutParams(-1,dp(54)));policies.setOnClickListener(v->listRecords(true));s.addView(body);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    private void scanDocument(){new AlertDialog.Builder(this).setTitle("Capturar documento").setMessage("Fotografía un DNI/NIE o una póliza. El sistema intentará diferenciarlos automáticamente.").setNegativeButton("Cancelar",null).setPositiveButton("Cámara",(d,w)->openCamera()).show();}
    private void openCamera(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},CAMERA_REQ);return;}try{File dir=new File(getCacheDir(),"scans");if(!dir.exists())dir.mkdirs();cameraFile=File.createTempFile("rgapro_",".jpg",dir);Uri uri=FileProvider.getUriForFile(this,getPackageName()+".fileprovider",cameraFile);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,uri);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);startActivityForResult(i,CAMERA_REQ);}catch(Exception e){Toast.makeText(this,"No se pudo abrir la cámara",Toast.LENGTH_LONG).show();}}
    private void pickImage(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,false);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMAGE_REQ);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK)return;try{if(request==CAMERA_REQ&&cameraFile!=null){sessionPaths.clear();sessionPaths.add(cameraFile.getAbsolutePath());runOcr(cameraFile.getAbsolutePath());}else if(request==IMAGE_REQ&&data!=null&&data.getData()!=null){String path=copyUri(data.getData());if(path!=null){sessionPaths.clear();sessionPaths.add(path);runOcr(path);}}}catch(Exception e){Toast.makeText(this,"No se pudo procesar la imagen",Toast.LENGTH_LONG).show();}}
    private String copyUri(Uri uri)throws IOException{File dir=new File(getFilesDir(),"documents");if(!dir.exists())dir.mkdirs();File out=new File(dir,"doc_"+System.currentTimeMillis()+".jpg");InputStream in=getContentResolver().openInputStream(uri);if(in==null)return null;FileOutputStream os=new FileOutputStream(out);byte[] b=new byte[8192];int n;while((n=in.read(b))>0)os.write(b,0,n);in.close();os.close();return out.getAbsolutePath();}
    private void runOcr(String path){Toast.makeText(this,"Leyendo documento…",Toast.LENGTH_SHORT).show();new Thread(()->{try{BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=2;Bitmap bm=BitmapFactory.decodeFile(path,o);if(bm==null)throw new IOException("Imagen no válida");InputImage image=InputImage.fromBitmap(bm,0);TextRecognizer rec=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);rec.process(image).addOnSuccessListener(r->{String text=r.getText();bm.recycle();rec.close();runOnUiThread(()->showSmartResult(text));}).addOnFailureListener(e->{bm.recycle();rec.close();runOnUiThread(()->Toast.makeText(this,"OCR no disponible: "+e.getMessage(),Toast.LENGTH_LONG).show());});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"No se pudo leer el documento",Toast.LENGTH_LONG).show());}}).start();}
    private void showSmartResult(String raw){SmartOcrProcessor.Result result=SmartOcrProcessor.process(raw);if(result.classification.type==DocumentType.UNKNOWN){new AlertDialog.Builder(this).setTitle("Documento no reconocido").setMessage("No hay suficiente evidencia para decidir si es DNI/NIE o póliza.").setNegativeButton("Descartar",null).setPositiveButton("Es DNI/NIE",(d,w)->showDniForm(DniOcrParser.parse(raw),raw)).setNeutralButton("Es póliza",(d,w)->showPolicyForm(PolicyOcrParser.parse(raw),raw)).show();}else if(result.classification.type==DocumentType.DNI_NIE)showDniForm(result.dni,raw);else showPolicyForm(result.policy,raw);}
    private void showDniForm(DniOcrParser.Result d,String raw){LinearLayout box=col();box.setPadding(dp(10),dp(4),dp(10),dp(4));box.addView(tv("🪪 DNI / NIE detectado · "+d.confidence+"%",15,BLUE,true));EditText name=edit("Nombre"),surname=edit("Apellidos"),dni=edit("Número de DNI/NIE ⭐"),birth=edit("Fecha de nacimiento"),phone=edit("Teléfono · manual"),address=edit("Dirección · manual"),email=edit("Email · manual");name.setText(d.name);surname.setText(d.surname);dni.setText(d.dni);birth.setText(d.birthDate);box.addView(tv("Datos del DNI",14,MUTED,true));add(box,name);add(box,surname);add(box,dni);add(box,birth);box.addView(tv("Datos de contacto",14,MUTED,true));add(box,phone);add(box,address);add(box,email);ScrollView scroll=new ScrollView(this);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Datos detectados por OCR").setView(scroll).setNegativeButton("Descartar",null).setPositiveButton("Guardar cliente",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{if(dni.getText().toString().trim().isEmpty()){dni.setError("El DNI/NIE es obligatorio");return;}saveClient(name,surname,dni,birth,phone,address,email,raw);dialog.dismiss();}));dialog.show();}
    private void showPolicyForm(PolicyOcrParser.Result p,String raw){LinearLayout box=col();box.setPadding(dp(10),dp(4),dp(10),dp(4));box.addView(tv("🛡 Póliza detectada · "+p.confidence+"%",15,BLUE,true));EditText number=edit("Número de póliza ⭐"),type=edit("Tipo de póliza"),expiry=edit("Vencimiento ⭐"),insurer=edit("Compañía aseguradora"),clientDni=edit("DNI/NIE del cliente · opcional");number.setText(p.policyNumber);type.setText(p.policyType);expiry.setText(p.expiryDate);insurer.setText(p.insurer);box.addView(tv("Datos de la póliza",14,MUTED,true));add(box,number);add(box,type);add(box,expiry);add(box,insurer);box.addView(tv("Asociación",14,MUTED,true));add(box,clientDni);ScrollView scroll=new ScrollView(this);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Póliza detectada").setView(scroll).setNegativeButton("Descartar",null).setPositiveButton("Guardar póliza",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{if(number.getText().toString().trim().isEmpty()){number.setError("Número de póliza obligatorio");return;}savePolicy(number,type,expiry,insurer,clientDni,raw);dialog.dismiss();}));dialog.show();}
    private void add(LinearLayout b,EditText e){b.addView(e,new LinearLayout.LayoutParams(-1,dp(52)));}
    private void saveClient(EditText name,EditText surname,EditText dni,EditText birth,EditText phone,EditText address,EditText email,String raw){try{JSONArray a=data();String id=dni.getText().toString().trim().toUpperCase(Locale.ROOT);JSONObject p=findById(a,id);if(p==null)p=new JSONObject();p.put("recordType","CLIENT");p.put("identityType",id.matches("[XYZ].*")?"NIE":"DNI");p.put("identityNumber",id);p.put("holderDni",id);p.put("name",name.getText().toString().trim());p.put("surname",surname.getText().toString().trim());p.put("holder",(name.getText().toString().trim()+" "+surname.getText().toString().trim()).trim());p.put("birthDate",birth.getText().toString().trim());p.put("phone",phone.getText().toString().trim());p.put("address",address.getText().toString().trim());p.put("email",email.getText().toString().trim());p.put("ocrText",raw);p.put("updatedAt",System.currentTimeMillis());attach(p);replaceOrAdd(a,p,id);save(a);Toast.makeText(this,"Cliente guardado",Toast.LENGTH_LONG).show();home();}catch(Exception e){Toast.makeText(this,"No se pudo guardar: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
    private void savePolicy(EditText number,EditText type,EditText expiry,EditText insurer,EditText clientDni,String raw){try{JSONArray a=data();JSONObject p=new JSONObject();p.put("recordType","POLICY");p.put("number",number.getText().toString().trim());p.put("type",type.getText().toString().trim());p.put("expiry",expiry.getText().toString().trim());p.put("validityDate",expiry.getText().toString().trim());p.put("insurer",insurer.getText().toString().trim());p.put("identityNumber",clientDni.getText().toString().trim().toUpperCase(Locale.ROOT));p.put("ocrText",raw);p.put("updatedAt",System.currentTimeMillis());attach(p);a.put(p);save(a);Toast.makeText(this,"Póliza guardada",Toast.LENGTH_LONG).show();home();}catch(Exception e){Toast.makeText(this,"No se pudo guardar: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
    private void attach(JSONObject p)throws Exception{if(sessionPaths.isEmpty())return;JSONArray docs=p.optJSONArray("documentPhotos");if(docs==null)docs=new JSONArray();for(String path:sessionPaths){JSONObject d=new JSONObject();d.put("path",path);d.put("addedAt",System.currentTimeMillis());docs.put(d);}p.put("documentPhotos",docs);}
    private JSONObject findById(JSONArray a,String id){for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&id.equalsIgnoreCase(p.optString("identityNumber",p.optString("holderDni",""))))return p;}return null;}
    private void replaceOrAdd(JSONArray a,JSONObject p,String id){for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&id.equalsIgnoreCase(x.optString("identityNumber",x.optString("holderDni","")))){a.put(i,p);return;}}a.put(p);}
    private JSONArray data(){try{return new JSONArray(prefs.getString("policies","[]"));}catch(Exception e){return new JSONArray();}}
    private void save(JSONArray a){prefs.edit().putString("policies",a.toString()).apply();}
    private void listRecords(boolean policies){LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout head=col();head.setBackgroundColor(NAVY);Button back=button("‹  Volver",false);back.setOnClickListener(v->home());head.addView(back,new LinearLayout.LayoutParams(-1,dp(52)));head.addView(tv(policies?"Pólizas":"Clientes",22,Color.WHITE,true));root.addView(head);ScrollView s=new ScrollView(this);LinearLayout list=col();list.setPadding(dp(16),dp(16),dp(16),dp(20));JSONArray a=data();int count=0;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null)continue;boolean isPolicy="POLICY".equals(p.optString("recordType"));if(isPolicy!=policies)continue;String label=policies?"🛡 "+p.optString("number","—")+" · "+p.optString("type","—")+"\n"+p.optString("insurer","")+" · vence "+p.optString("expiry","—"):"👤 "+p.optString("name","")+" "+p.optString("surname","")+"\nDNI/NIE: "+p.optString("identityNumber","—");list.addView(button(label,false),new LinearLayout.LayoutParams(-1,dp(76)));count++;}if(count==0)list.addView(tv(policies?"No hay pólizas guardadas.":"No hay clientes guardados.",16,MUTED,false));s.addView(list);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    private void populateExpiries(LinearLayout list){JSONArray a=data();Calendar now=Calendar.getInstance();boolean any=false;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null||!"POLICY".equals(p.optString("recordType")))continue;String ex=p.optString("expiry","");if(ex.isEmpty())continue;try{String[] z=ex.replace('.','/').replace('-','/').split("/");if(z.length!=3)continue;Calendar d=Calendar.getInstance();d.set(Integer.parseInt(z[2]),Integer.parseInt(z[1])-1,Integer.parseInt(z[0]));long days=(d.getTimeInMillis()-now.getTimeInMillis())/86400000L;if(days>=0&&days<=60){any=true;list.addView(tv("⚠ "+p.optString("number","—")+" · "+p.optString("type","Póliza")+"\nVence "+ex+" · "+days+" días",15,TEXT,true));}}catch(Exception ignored){}}if(!any)list.addView(tv("No hay pólizas que venzan en los próximos 60 días.",14,MUTED,false));}
}
